/* Lei seca da Revisão — redação oficial, sem texto autoral. Gerado por scripts/build-lei-revisao.mjs. */
(function(g){g.BC_LEI_REVISAO=g.BC_LEI_REVISAO||{};g.BC_LEI_REVISAO["adm"]=g.BC_LEI_REVISAO["adm"]||{};g.BC_LEI_REVISAO["adm"][9]=[{"key":"cf:175","law":"cf","ref":"175","label":"Constituição Federal · CF/88 · Art. 175","paragraphs":["Art. 175. Incumbe ao poder público, na forma da lei, diretamente ou sob regime de concessão ou permissão, sempre através de licitação, a prestação de serviços públicos.","Parágrafo único. A lei disporá sobre:","I - o regime das empresas concessionárias e permissionárias de serviços públicos, o caráter especial de seu contrato e de sua prorrogação, bem como as condições de caducidade, fiscalização e rescisão da concessão ou permissão;","II - os direitos dos usuários;","III - política tarifária;","IV - a obrigação de manter serviço adequado."],"url":""},{"key":"l8987:5","law":"l8987","ref":"5","label":"Lei de Concessões e Permissões · Art. 5","paragraphs":["Art. 5º O poder concedente publicará, previamente ao edital de licitação, ato justificando a conveniência da outorga de concessão ou permissão, caracterizando seu objeto, área e prazo."],"url":""},{"key":"l9074:2","law":"l9074","ref":"2","label":"Lei 9.074/1995 · Art. 2","paragraphs":["Art. 2º É vedado à União, aos Estados, ao Distrito Federal e aos Municípios executarem obras e serviços públicos por meio de concessão e permissão de serviço público, sem lei que lhes autorize e fixe os termos, dispensada a lei autorizativa nos casos de saneamento básico e limpeza urbana e nos já referidos na Constituição Federal, nas Constituições Estaduais e nas Leis Orgânicas do Distrito Federal e Municípios, observado, em qualquer caso, os termos da Lei nº 8.987, de 1995.","§ 1º A contratação dos serviços e obras públicas resultantes dos processos iniciados com base na Lei nº 8.987, de 1995, entre a data de sua publicação e a da presente Lei, fica dispensada de lei autorizativa.","§ 2º Independe de concessão, permissão ou autorização o transporte de cargas pelos meios rodoviário e aquaviário. (Parágrafo com redação dada pela Lei nº 9.432, de 8/1/1997)","§ 3º Independe de concessão ou permissão o transporte:","I - aquaviário, de passageiros, que não seja realizado entre portos organizados;","II - rodoviário e aquaviário de pessoas, realizado por operadoras de turismo no exercício dessa atividade;","III - de pessoas, em caráter privativo de organizações públicas ou privadas, ainda que em forma regular.","§ 4º A outorga para exploração indireta de ferrovias em regime de direito privado será exercida mediante autorização, na forma da legislação específica. (Parágrafo acrescido pela Lei nº 14.273, de 23/12/2021, publicada na Edição Extra C do DOU de 23/12/2021, em vigor 45 dias após a publicação)"],"url":""},{"key":"l8987:16","law":"l8987","ref":"16","label":"Lei de Concessões e Permissões · Art. 16","paragraphs":["Art. 16. A outorga de concessão ou permissão não terá caráter de exclusividade, salvo no caso de inviabilidade técnica ou econômica justificada no ato a que se refere o art. 5º desta Lei."],"url":""},{"key":"l8987:6","law":"l8987","ref":"6","label":"Lei de Concessões e Permissões · Art. 6","paragraphs":["Art. 6º Toda concessão ou permissão pressupõe a prestação de serviço adequado ao pleno atendimento dos usuários, conforme estabelecido nesta Lei, nas normas pertinentes e no respectivo contrato.","§ 1º Serviço adequado é o que satisfaz as condições de regularidade, continuidade, eficiência, segurança, atualidade, generalidade, cortesia na sua prestação e modicidade das tarifas.","§ 2º A atualidade compreende a modernidade das técnicas, do equipamento e das instalações e a sua conservação, bem como a melhoria e expansão do serviço.","§ 3º Não se caracteriza como descontinuidade do serviço a sua interrupção em situação de emergência ou após prévio aviso, quando:","I - motivada por razões de ordem técnica ou de segurança das instalações; e,","II - por inadimplemento do usuário, considerado o interesse da coletividade.","§ 4º A interrupção do serviço na hipótese prevista no inciso II do § 3º deste artigo não poderá iniciar-se na sexta-feira, no sábado ou no domingo, nem em feriado ou no dia anterior a feriado. (Parágrafo acrescido pela Lei nº 14.015, de 15/6/2020)"],"url":""},{"key":"l8987:13","law":"l8987","ref":"13","label":"Lei de Concessões e Permissões · Art. 13","paragraphs":["Art. 13. As tarifas poderão ser diferenciadas em função das características técnicas e dos custos específicos provenientes do atendimento aos distintos segmentos de usuários."],"url":""},{"key":"l8987:2","law":"l8987","ref":"2","label":"Lei de Concessões e Permissões · Art. 2","paragraphs":["Art. 2º Para os fins do disposto nesta Lei, considera-se:","I - poder concedente: a União, o Estado, o Distrito Federal ou o Município, em cuja competência se encontre o serviço público, precedido ou não da execução de obra pública, objeto de concessão ou permissão;","II - concessão de serviço público: a delegação de sua prestação, feita pelo poder concedente, mediante licitação, na modalidade concorrência ou diálogo competitivo, a pessoa jurídica ou consórcio de empresas que demonstre capacidade para seu desempenho, por sua conta e risco e por prazo determinado; ( Inciso com redação dada pela Lei nº 14.133, de 1º/4/2021)","III - concessão de serviço público precedida da execução de obra pública: a construção, total ou parcial, conservação, reforma, ampliação ou melhoramento de quaisquer obras de interesse público, delegados pelo poder concedente, mediante licitação, na modalidade concorrência ou diálogo competitivo, a pessoa jurídica ou consórcio de empresas que demonstre capacidade para a sua realização, por sua conta e risco, de forma que o investimento da concessionária seja remunerado e amortizado mediante a exploração do serviço ou da obra por prazo determinado ; ( Inciso com redação dada pela Lei nº 14.133, de 1º/4/2021)","IV - permissão de serviço público: a delegação, a título precário, mediante licitação, da prestação de serviços públicos, feita pelo poder concedente à pessoa física ou jurídica que demonstre capacidade para seu desempenho, por sua conta e risco."],"url":""},{"key":"l8987:14","law":"l8987","ref":"14","label":"Lei de Concessões e Permissões · Art. 14","paragraphs":["Art. 14. Toda concessão de serviço público, precedida ou não da execução de obra pública, será objeto de prévia licitação, nos termos da legislação própria e com observância dos princípios da legalidade, moralidade, publicidade, igualdade, do julgamento por critérios objetivos e da vinculação ao instrumento convocatório."],"url":""},{"key":"l8987:40","law":"l8987","ref":"40","label":"Lei de Concessões e Permissões · Art. 40","paragraphs":["Art. 40. A permissão de serviço público será formalizada mediante contrato de adesão, que observará os termos desta Lei, das demais normas pertinentes e do edital de licitação, inclusive quanto à precariedade e à revogabilidade unilateral do contrato pelo poder concedente.","Parágrafo único. Aplica-se às permissões o disposto nesta Lei."],"url":""},{"key":"cf:21","law":"cf","ref":"21","label":"Constituição Federal · CF/88 · Art. 21","paragraphs":["Art. 21. Compete à União:","I - manter relações com Estados estrangeiros e participar de organizações internacionais;","II - declarar a guerra e celebrar a paz;","III - assegurar a defesa nacional;","IV - permitir, nos casos previstos em lei complementar, que forças estrangeiras transitem pelo território nacional ou nele permaneçam temporariamente;","V - decretar o estado de sítio, o estado de defesa e a intervenção federal;","VI - autorizar e fiscalizar a produção e o comércio de material bélico;","VII - emitir moeda;","VIII - administrar as reservas cambiais do País e fiscalizar as operações de natureza financeira, especialmente as de crédito, câmbio e capitalização, bem como as de seguros e de previdência privada;","IX - elaborar e executar planos nacionais e regionais de ordenação do território e de desenvolvimento econômico e social;","X - manter o serviço postal e o correio aéreo nacional;","XI - explorar, diretamente ou mediante autorização, concessão ou permissão, os serviços de telecomunicações, nos termos da lei, que disporá sobre a organização dos serviços, a criação de um órgão regulador e outros aspectos institucionais; (Inciso com redação dada pela Emenda Constitucional nº 8, de 1995)","XII - explorar, diretamente ou mediante autorização, concessão ou permissão:","a) os serviços de radiodifusão sonora e de sons e imagens; (Alínea com redação dada pela Emenda Constitucional nº 8, de 1995)","b) os serviços e instalações de energia elétrica e o aproveitamento energético dos cursos de água, em articulação com os Estados onde se situam os potenciais hidroenergéticos;","c) a navegação aérea, aeroespacial e a infra-estrutura aeroportuária;","d) os serviços de transporte ferroviário e aquaviário entre portos brasileiros e fronteiras nacionais, ou que transponham os limites de Estado ou Território;","e) os serviços de transporte rodoviário interestadual e internacional de passageiros;","f) os portos marítimos, fluviais e lacustres;","XIII - organizar e manter o Poder Judiciário, o Ministério Público do Distrito Federal e dos Territórios e a Defensoria Pública dos Territórios; (Inciso com redação dada pela Emenda Constitucional nº 69, de 2012, publicada no DOU de 30/3/2012, produzindo efeitos 120 dias após a publicação)","XIV - organizar e manter a polícia civil, a polícia penal, a polícia militar e o corpo de bombeiros militar do Distrito Federal, bem como prestar assistência financeira ao Distrito Federal para a execução de serviços públicos, por meio de fundo próprio; (Inciso com redação dada pela Emenda Constitucional nº 104, de 2019)","XV - organizar e manter os serviços oficiais de estatística, geografia, geologia e cartografia de âmbito nacional;","XVI - exercer a classificação, para efeito indicativo, de diversões públicas e de programas de rádio e televisão;","XVII - conceder anistia;","XVIII - planejar e promover a defesa permanente contra as calamidades públicas, especialmente as secas e as inundações;","XIX - instituir sistema nacional de gerenciamento de recursos hídricos e definir critérios de outorga de direitos de seu uso;","XX - instituir diretrizes para o desenvolvimento urbano, inclusive habitação, saneamento básico e transportes urbanos;","XXI - estabelecer princípios e diretrizes para o sistema nacional de viação;","XXII - executar os serviços de polícia marítima, aeroportuária e de fronteiras; (Inciso com redação dada pela Emenda Constitucional nº 19, de 1998)","XXIII - explorar os serviços e instalações nucleares de qualquer natureza e exercer monopólio estatal sobre a pesquisa, a lavra, o enriquecimento e reprocessamento, a industrialização e o comércio de minérios nucleares e seus derivados, atendidos os seguintes princípios e condições:","a) toda atividade nuclear em território nacional somente será admitida para fins pacíficos e mediante aprovação do Congresso Nacional;","b) sob regime de permissão, são autorizadas a comercialização e a utilização de radioisótopos para pesquisa e uso agrícolas e industriais; (Alínea com redação dada pela Emenda Constitucional nº 118, de 2022)","c) sob regime de permissão, são autorizadas a produção, a comercialização e a utilização de radioisótopos para pesquisa e uso médicos; (Alínea acrescida pela Emenda Constitucional nº 49, de 2006, com redação dada pela Emenda Constitucional nº 118, de 2022)","d) a responsabilidade civil por danos nucleares independe da existência de culpa; (Primitiva alínea c renomeada pela Emenda Constitucional nº 49, de 2006)","XXIV - organizar, manter e executar a inspeção do trabalho;","XXV - estabelecer as áreas e as condições para o exercício da atividade de garimpagem, em forma associativa.","XXVI - organizar e fiscalizar a proteção e o tratamento de dados pessoais, nos termos da lei. (Inciso acrescido pela Emenda Constitucional nº 115, de 2022)"],"url":""},{"key":"l8987:29","law":"l8987","ref":"29","label":"Lei de Concessões e Permissões · Art. 29","paragraphs":["Art. 29. Incumbe ao poder concedente:","I - regulamentar o serviço concedido e fiscalizar permanentemente a sua prestação;","II - aplicar as penalidades regulamentares e contratuais;","III - intervir na prestação do serviço, nos casos e condições previstos em lei;","IV - extinguir a concessão, nos casos previstos nesta Lei e na forma prevista no contrato;","V - homologar reajustes e proceder à revisão das tarifas na forma desta Lei, das normas pertinentes e do contrato;","VI - cumprir e fazer cumprir as disposições regulamentares do serviço e as cláusulas contratuais da concessão;","VII - zelar pela boa qualidade do serviço, receber, apurar e solucionar queixas e reclamações dos usuários, que serão cientificados, em até trinta dias, das providências tomadas;","VIII - declarar de utilidade pública os bens necessários à execução do serviço ou obra pública, promovendo as desapropriações, diretamente ou mediante outorga de poderes à concessionária, caso em que será desta a responsabilidade pelas indenizações cabíveis;","IX - declarar de necessidade ou utilidade pública, para fins de instituição de servidão administrativa, os bens necessários à execução de serviço ou obra pública, promovendo-a diretamente ou mediante outorga de poderes à concessionária, caso em que será desta a responsabilidade pelas indenizações cabíveis;","X - estimular o aumento da qualidade, produtividade, preservação do meio-ambiente e conservação;","XI - incentivar a competitividade; e","XII - estimular a formação de associações de usuários para defesa de interesses relativos ao serviço."],"url":""},{"key":"l8987:30","law":"l8987","ref":"30","label":"Lei de Concessões e Permissões · Art. 30","paragraphs":["Art. 30. No exercício da fiscalização, o poder concedente terá acesso aos dados relativos à administração, contabilidade, recursos técnicos, econômicos e financeiros da concessionária.","Parágrafo único. A fiscalização do serviço será feita por intermédio de órgão técnico do poder concedente ou por entidade com ele conveniada, e, periodicamente, conforme previsto em norma regulamentar, por comissão composta de representantes do poder concedente, da concessionária e dos usuários."],"url":""},{"key":"l8987:31","law":"l8987","ref":"31","label":"Lei de Concessões e Permissões · Art. 31","paragraphs":["Art. 31. Incumbe à concessionária:","I - prestar serviço adequado, na forma prevista nesta Lei, nas normas técnicas aplicáveis e no contrato;","II - manter em dia o inventário e o registro dos bens vinculados à concessão;","III - prestar contas da gestão do serviço ao poder concedente e aos usuários, nos termos definidos no contrato;","IV - cumprir e fazer cumprir as normas do serviço e as cláusulas contratuais da concessão;","V - permitir aos encarregados da fiscalização livre acesso, em qualquer época, às obras, aos equipamentos e às instalações integrantes do serviço, bem como a seus registros contábeis;","VI - promover as desapropriações e constituir servidões autorizadas pelo poder concedente, conforme previsto no edital e no contrato;","VII - zelar pela integridade dos bens vinculados à prestação do serviço, bem como segurá-los adequadamente; e","VIII - captar, aplicar e gerir os recursos financeiros necessários à prestação do serviço.","IX - (VETADO na Lei nº 13.448, de 5/6/2017)","Parágrafo único. As contratações, inclusive de mão-de-obra, feitas pela concessionária serão regidas pelas disposições de direito privado e pela legislação trabalhista, não se estabelecendo qualquer relação entre os terceiros contratados pela concessionária e o poder concedente."],"url":""},{"key":"l8987:25","law":"l8987","ref":"25","label":"Lei de Concessões e Permissões · Art. 25","paragraphs":["Art. 25. Incumbe à concessionária a execução do serviço concedido, cabendo-lhe responder por todos os prejuízos causados ao poder concedente, aos usuários ou a terceiros, sem que a fiscalização exercida pelo órgão competente exclua ou atenue essa responsabilidade.","§ 1º Sem prejuízo da responsabilidade a que se refere este artigo, a concessionária poderá contratar com terceiros o desenvolvimento de atividades inerentes, acessórias ou complementares ao serviço concedido, bem como a implementação de projetos associados.","§ 2º Os contratos celebrados entre a concessionária e os terceiros a que se refere o parágrafo anterior reger-se-ão pelo direito privado, não se estabelecendo qualquer relação jurídica entre os terceiros e o poder concedente.","§ 3º A execução das atividades contratadas com terceiros pressupõe o cumprimento das normas regulamentares da modalidade do serviço concedido."],"url":""},{"key":"l8987:7","law":"l8987","ref":"7","label":"Lei de Concessões e Permissões · Art. 7","paragraphs":["Art. 7º Sem prejuízo do disposto na Lei nº 8.078, de 11 de setembro de 1990, são direitos e obrigações dos usuários:","I - receber serviço adequado;","II - receber do poder concedente e da concessionária informações para a defesa de interesses individuais ou coletivos;","III - obter e utilizar o serviço, com liberdade de escolha entre vários prestadores de serviços, quando for o caso, observadas as normas do poder concedente. (Inciso com redação dada pela Lei nº 9.648, de 27/5/1998)","IV - levar ao conhecimento do poder público e da concessionária as irregularidades de que tenham conhecimento, referentes ao serviço prestado;","V - comunicar às autoridades competentes os atos ilícitos praticados pela concessionária na prestação do serviço;","VI - contribuir para a permanência das boas condições dos bens públicos através dos quais lhes são prestados os serviços."],"url":""},{"key":"l8987:7-A","law":"l8987","ref":"7-A","label":"Lei de Concessões e Permissões · Art. 7-A","paragraphs":["Art. 7º-A As concessionárias de serviços públicos, de direito público e privado, nos Estados e no Distrito Federal, são obrigadas a oferecer ao consumidor e ao usuário, dentro do mês de vencimento, o mínimo de seis datas opcionais para escolherem os dias de vencimento de seus débitos.","Parágrafo único. (VETADO) (Artigo acrescido pela Lei nº 9.791, de 24/3/1999)"],"url":""},{"key":"cf:37","law":"cf","ref":"37","label":"Constituição Federal · CF/88 · Art. 37","paragraphs":["Art. 37. A administração pública direta e indireta de qualquer dos Poderes da União, dos Estados, do Distrito Federal e dos Municípios obedecerá aos princípios de legalidade, impessoalidade, moralidade, publicidade e eficiência e, também, ao seguinte: (“Caput” do artigo com redação dada pela Emenda Constitucional nº 19, de 1998)","I - os cargos, empregos e funções públicas são acessíveis aos brasileiros que preencham os requisitos estabelecidos em lei, assim como aos estrangeiros, na forma da lei; (Inciso com redação dada pela Emenda Constitucional nº 19, de 1998)","II - a investidura em cargo ou emprego público depende de aprovação prévia em concurso público de provas ou de provas e títulos, de acordo com a natureza e a complexidade do cargo ou emprego, na forma prevista em lei, ressalvadas as nomeações para cargo em comissão declarado em lei de livre nomeação e exoneração; (Inciso com redação dada pela Emenda Constitucional nº 19, de 1998)","III - o prazo de validade do concurso público será de até dois anos, prorrogável uma vez, por igual período;","IV - durante o prazo improrrogável previsto no edital de convocação, aquele aprovado em concurso público de provas ou de provas e títulos será convocado com prioridade sobre novos concursados para assumir cargo ou emprego, na carreira;","V - as funções de confiança, exercidas exclusivamente por servidores ocupantes de cargo efetivo, e os cargos em comissão, a serem preenchidos por servidores de carreira nos casos, condições e percentuais mínimos previstos em lei, destinam-se apenas às atribuições de direção, chefia e assessoramento; (Inciso com redação dada pela Emenda Constitucional nº 19, de 1998)","VI - é garantido ao servidor público civil o direito à livre associação sindical;","VII - o direito de greve será exercido nos termos e nos limites definidos em lei específica; (Inciso com redação dada pela Emenda Constitucional nº 19, de 1998)","VIII - a lei reservará percentual dos cargos e empregos públicos para as pessoas portadoras de deficiência e definirá os critérios de sua admissão;","IX - a lei estabelecerá os casos de contratação por tempo determinado para atender a necessidade temporária de excepcional interesse público;","X - a remuneração dos servidores públicos e o subsídio de que trata o § 4º do art. 39 somente poderão ser fixados ou alterados por lei específica, observada a iniciativa privativa em cada caso, assegurada revisão geral anual, sempre na mesma data e sem distinção de índices; (Inciso com redação dada pela Emenda Constitucional nº 19, de 1998)","XI - a remuneração e o subsídio dos ocupantes de cargos, funções e empregos públicos da administração direta, autárquica e fundacional, dos membros de qualquer dos Poderes da União, dos Estados, do Distrito Federal e dos Municípios, dos detentores de mandato eletivo e dos demais agentes políticos e os proventos, pensões ou outra espécie remuneratória, percebidos cumulativamente ou não, incluídas as vantagens pessoais ou de qualquer outra natureza, não poderão exceder o subsídio mensal, em espécie, dos Ministros do Supremo Tribunal Federal, aplicando-se como limite, nos Municípios, o subsídio do Prefeito, e nos Estados e no Distrito Federal, o subsídio mensal do Governador no âmbito do Poder Executivo, o subsídio dos Deputados Estaduais e Distritais no âmbito do Poder Legislativo e o subsídio dos Desembargadores do Tribunal de Justiça, limitado a noventa inteiros e vinte e cinco centésimos por cento do subsídio mensal, em espécie, dos Ministros do Supremo Tribunal Federal, no âmbito do Poder Judiciário, aplicável este limite aos membros do Ministério Público, aos Procuradores e aos Defensores Públicos; (Inciso com redação dada pela Emenda Constitucional nº 41, de 2003)","XII - os vencimentos dos cargos do Poder Legislativo e do Poder Judiciário não poderão ser superiores aos pagos pelo Poder Executivo;","XIII - é vedada a vinculação ou equiparação de quaisquer espécies remuneratórias para o efeito de remuneração de pessoal do serviço público; (Inciso com redação dada pela Emenda Constitucional nº 19, de 1998)","XIV - os acréscimos pecuniários percebidos por servidor público não serão computados nem acumulados para fins de concessão de acréscimos ulteriores; (Inciso com redação dada pela Emenda Constitucional nº 19, de 1998)","XV - o subsídio e os vencimentos dos ocupantes de cargos e empregos públicos são irredutíveis, ressalvado o disposto nos incisos XI e XIV deste artigo e nos arts. 39, § 4º, 150, II, 153, III, e 153, § 2º, I; (Inciso com redação dada pela Emenda Constitucional nº 19, de 1998)","XVI - é vedada a acumulação remunerada de cargos públicos, exceto, quando houver compatibilidade de horários, observado em qualquer caso o disposto no inciso XI: (“Caput” do inciso com redação dada pela Emenda Constitucional nº 19, de 1998)","a) a de dois cargos de professor;","b) a de um cargo de professor com outro de qualquer natureza; (Alínea com redação dada pela Emenda Constitucional nº 138, de 2025)","c) a de dois cargos ou empregos privativos de profissionais de saúde, com profissões regulamentadas; (Alínea com redação dada pela Emenda Constitucional nº 34, de 2001)","XVII - a proibição de acumular estende-se a empregos e funções e abrange autarquias, fundações, empresas públicas, sociedades de economia mista, suas subsidiárias, e sociedades controladas, direta ou indiretamente, pelo poder público; (Inciso com redação dada pela Emenda Constitucional nº 19, de 1998)","XVIII - a administração fazendária e seus servidores fiscais terão, dentro de suas áreas de competência e jurisdição, precedência sobre os demais setores administrativos, na forma da lei;","XIX - somente por lei específica poderá ser criada autarquia e autorizada a instituição de empresa pública, de sociedade de economia mista e de fundação, cabendo à lei complementar, neste último caso, definir as áreas de sua atuação; (Inciso com redação dada pela Emenda Constitucional nº 19, de 1998)","XX - depende de autorização legislativa, em cada caso, a criação de subsidiárias das entidades mencionadas no inciso anterior, assim como a participação de qualquer delas em empresa privada;","XXI - ressalvados os casos especificados na legislação, as obras, serviços, compras e alienações serão contratados mediante processo de licitação pública que assegure igualdade de condições a todos os concorrentes, com cláusulas que estabeleçam obrigações de pagamento, mantidas as condições efetivas da proposta, nos termos da lei, o qual somente permitirá as exigências de qualificação técnica e econômica indispensáveis à garantia do cumprimento das obrigações.","XXII - as administrações tributárias da União, dos Estados, do Distrito Federal e dos Municípios, atividades essenciais ao funcionamento do Estado, exercidas por servidores de carreiras específicas, terão recursos prioritários para a realização de suas atividades e atuarão de forma integrada, inclusive com o compartilhamento de cadastros e de informações fiscais, na forma da lei ou convênio. (Inciso acrescido pela Emenda Constitucional nº 42, de 2003)","§ 1º A publicidade dos atos, programas, obras, serviços e campanhas dos órgãos públicos deverá ter caráter educativo, informativo ou de orientação social, dela não podendo constar nomes, símbolos ou imagens que caracterizem promoção pessoal de autoridades ou servidores públicos.","§ 2º A não-observância do disposto nos incisos II e III implicará a nulidade do ato e a punição da autoridade responsável, nos termos da lei.","§ 3º A lei disciplinará as formas de participação do usuário na administração pública direta e indireta, regulando especialmente:","I - as reclamações relativas à prestação dos serviços públicos em geral, asseguradas a manutenção de serviços de atendimento ao usuário e a avaliação periódica, externa e interna, da qualidade dos serviços;","II - o acesso dos usuários a registros administrativos e a informações sobre atos de governo, observado o disposto no art. 5º, X e XXXIII;","III - a disciplina da representação contra o exercício negligente ou abusivo de cargo, emprego ou função na administração pública. (Parágrafo com redação dada pela Emenda Constitucional nº 19, de 1998)","§ 4º Os atos de improbidade administrativa importarão a suspensão dos direitos políticos, a perda da função pública, a indisponibilidade dos bens e o ressarcimento ao erário, na forma e gradação previstas em lei, sem prejuízo da ação penal cabível.","§ 5º A lei estabelecerá os prazos de prescrição para ilícitos praticados por qualquer agente, servidor ou não, que causem prejuízos ao erário, ressalvadas as respectivas ações de ressarcimento.","§ 6º As pessoas jurídicas de direito público e as de direito privado prestadoras de serviços públicos responderão pelos danos que seus agentes, nessa qualidade, causarem a terceiros, assegurado o direito de regresso contra o responsável nos casos de dolo ou culpa.","§ 7º A lei disporá sobre os requisitos e as restrições ao ocupante de cargo ou emprego da administração direta e indireta que possibilite o acesso a informações privilegiadas. (Parágrafo acrescido pela Emenda Constitucional nº 19, de 1998)","§ 8º A autonomia gerencial, orçamentária e financeira dos órgãos e entidades da administração direta e indireta poderá ser ampliada mediante contrato, a ser firmado entre seus administradores e o poder público, que tenha por objeto a fixação de metas de desempenho para o órgão ou entidade, cabendo à lei dispor sobre:","I - o prazo de duração do contrato;","II - os controles e critérios de avaliação de desempenho, direitos, obrigações e responsabilidade dos dirigentes;","III - a remuneração do pessoal. (Parágrafo acrescido pela Emenda Constitucional nº 19, de 1998)","§ 9º O disposto no inciso XI aplica-se às empresas públicas e às sociedades de economia mista, e suas subsidiárias, que receberem recursos da União, dos Estados, do Distrito Federal ou dos Municípios para pagamento de despesas de pessoal ou de custeio em geral. (Parágrafo acrescido pela Emenda Constitucional nº 19, de 1998)","§ 10. É vedada a percepção simultânea de proventos de aposentadoria decorrentes do art. 40 ou dos arts. 42 e 142 com a remuneração de cargo, emprego ou função pública, ressalvados os cargos acumuláveis na forma desta Constituição, os cargos eletivos e os cargos em comissão declarados em lei de livre nomeação e exoneração. (Parágrafo acrescido pela Emenda Constitucional nº 20, de 1998)","§ 11. Não serão computadas, para efeito dos limites remuneratórios de que trata o inciso XI do caput deste artigo, as parcelas de caráter indenizatório expressamente previstas em lei ordinária, aprovada pelo Congresso Nacional, de caráter nacional, aplicada a todos os Poderes e órgãos constitucionalmente autônomos. (Parágrafo acrescido pela Emenda Constitucional nº 47, de 2005, e com redação dada pela Emenda Constitucional nº 135, de 2024)","§ 12. Para os fins do disposto no inciso XI do caput deste artigo, fica facultado aos Estados e ao Distrito Federal fixar, em seu âmbito, mediante emenda às respectivas Constituições e Lei Orgânica, como limite único, o subsídio mensal dos Desembargadores do respectivo Tribunal de Justiça, limitado a noventa inteiros e vinte e cinco centésimos por cento do subsídio mensal dos Ministros do Supremo Tribunal Federal, não se aplicando o disposto neste parágrafo aos subsídios dos Deputados Estaduais e Distritais e dos Vereadores. (Parágrafo acrescido pela Emenda Constitucional nº 47, de 2005)","§ 13. O servidor público titular de cargo efetivo poderá ser readaptado para exercício de cargo cujas atribuições e responsabilidades sejam compatíveis com a limitação que tenha sofrido em sua capacidade física ou mental, enquanto permanecer nesta condição, desde que possua a habilitação e o nível de escolaridade exigidos para o cargo de destino, mantida a remuneração do cargo de origem. (Parágrafo acrescido pela Emenda Constitucional nº 103, de 2019)","§ 14. A aposentadoria concedida com a utilização de tempo de contribuição decorrente de cargo, emprego ou função pública, inclusive do Regime Geral de Previdência Social, acarretará o rompimento do vínculo que gerou o referido tempo de contribuição. (Parágrafo acrescido pela Emenda Constitucional nº 103, de 2019)","§ 15. É vedada a complementação de aposentadorias de servidores públicos e de pensões por morte a seus dependentes que não seja decorrente do disposto nos §§ 14 a 16 do art. 40 ou que não seja prevista em lei que extinga regime próprio de previdência social. (Parágrafo acrescido pela Emenda Constitucional nº 103, de 2019)","§ 16. Os órgãos e entidades da administração pública, individual ou conjuntamente, devem realizar avaliação das políticas públicas, inclusive com divulgação do objeto a ser avaliado e dos resultados alcançados, na forma da lei. (Parágrafo acrescido pela Emenda Constitucional nº 109, de 2021)","§ 17. (Vide Emenda Constitucional nº 132, de 2023)","§ 18. (Vide Emenda Constitucional nº 132, de 2023)"],"url":""},{"key":"l8987:9","law":"l8987","ref":"9","label":"Lei de Concessões e Permissões · Art. 9","paragraphs":["Art. 9º A tarifa do serviço público concedido será fixada pelo preço da proposta vencedora da licitação e preservada pelas regras de revisão previstas nesta Lei, no edital e no contrato.","§ 1º A tarifa não será subordinada à legislação específica anterior e somente nos casos expressamente previstos em lei, sua cobrança poderá ser condicionada à existência de serviço público alternativo e gratuito para o usuário. (Parágrafo com redação dada pela Lei nº 9.648, de 27/5/1998)","§ 2º Os contratos poderão prever mecanismos de revisão das tarifas, a fim de manter-se o equilíbrio econômico-financeiro.","§ 3º Ressalvados os impostos sobre a renda, a criação, alteração ou extinção de quaisquer tributos ou encargos legais, após a apresentação da proposta, quando comprovado seu impacto, implicará a revisão da tarifa, para mais ou para menos, conforme o caso.","§ 4º Em havendo alteração unilateral do contrato que afete o seu inicial equilíbrio econômico-financeiro, o poder concedente deverá restabelecê-lo, concomitantemente à alteração.","§ 5º A concessionária deverá divulgar em seu sítio eletrônico, de forma clara e de fácil compreensão pelos usuários, tabela com o valor das tarifas praticadas e a evolução das revisões ou reajustes realizados nos últimos cinco anos. (Parágrafo acrescido pela Lei nº 13.673, de 5/6/2018)"],"url":""},{"key":"l8987:11","law":"l8987","ref":"11","label":"Lei de Concessões e Permissões · Art. 11","paragraphs":["Art. 11. No atendimento às peculiaridades de cada serviço público, poderá o poder concedente prever, em favor da concessionária, no edital de licitação, a possibilidade de outras fontes provenientes de receitas alternativas, complementares, acessórias ou de projetos associados, com ou sem exclusividade, com vistas a favorecer a modicidade das tarifas, observado o disposto no art. 17 desta Lei.","Parágrafo único. As fontes de receita previstas neste artigo serão obrigatoriamente consideradas para a aferição do inicial equilíbrio econômico-financeiro do contrato."],"url":""},{"key":"l8987:18","law":"l8987","ref":"18","label":"Lei de Concessões e Permissões · Art. 18","paragraphs":["Art. 18. O edital de licitação será elaborado pelo poder concedente, observados, no que couber, os critérios e as normas gerais da legislação própria sobre licitações e contratos e conterá, especialmente:","I - o objeto, metas e prazo da concessão;","II - a descrição das condições necessárias à prestação adequada do serviço;","III - os prazos para recebimento das propostas, julgamento da licitação e assinatura do contrato;","IV - prazo, local e horário em que serão fornecidos, aos interessados, os dados, estudos e projetos necessários à elaboração dos orçamentos e apresentação das propostas;","V - os critérios e a relação dos documentos exigidos para a aferição da capacidade técnica, da idoneidade financeira e da regularidade jurídica e fiscal;","VI - as possíveis fontes de receitas alternativas, complementares ou acessórias, bem como as provenientes de projetos associados;","VII - os direitos e obrigações do poder concedente e da concessionária em relação a alterações e expansões a serem realizadas no futuro, para garantir a continuidade da prestação do serviço;","VIII - os critérios de reajuste e revisão da tarifa;","IX - os critérios, indicadores, fórmulas e parâmetros a serem utilizados no julgamento técnico e econômico-financeiro da proposta;","X - a indicação dos bens reversíveis;","XI - as características dos bens reversíveis e as condições em que estes serão postos à disposição, nos casos em que houver sido extinta a concessão anterior;","XII - a expressa indicação do responsável pelo ônus das desapropriações necessárias à execução do serviço ou da obra pública, ou para a instituição de servidão administrativa;","XIII - as condições de liderança da empresa responsável, na hipótese em que for permitida a participação de empresas em consórcio;","XIV - nos casos de concessão, a minuta do respectivo contrato, que conterá as cláusulas essenciais referidas no art. 23 desta Lei, quando aplicáveis;","XV - nos casos de concessão de serviços públicos precedida da execução de obra pública, os dados relativos à obra, dentre os quais os elementos do projeto básico que permitam sua plena caracterização, bem assim as garantias exigidas para essa parte específica do contrato, adequadas a cada caso e limitadas ao valor da obra; (Inciso com redação dada pela Lei nº 9.648, de 27/5/1998)","XVI - nos casos de permissão, os termos do contrato de adesão a ser firmado.","XVII – (VETADO na Lei nº 13.448, de 5/6/2017)"],"url":""},{"key":"l8987:23","law":"l8987","ref":"23","label":"Lei de Concessões e Permissões · Art. 23","paragraphs":["Art. 23. São cláusulas essenciais do contrato de concessão as relativas:","I - ao objeto, à área e ao prazo da concessão;","II - ao modo, forma e condições de prestação do serviço;","III - aos critérios, indicadores, fórmulas e parâmetros definidores da qualidade do serviço;","IV - ao preço do serviço e aos critérios e procedimentos para o reajuste e a revisão das tarifas;","V - aos direitos, garantias e obrigações do poder concedente e da concessionária, inclusive os relacionados às previsíveis necessidades de futura alteração e expansão do serviço e conseqüente modernização, aperfeiçoamento e ampliação dos equipamentos e das instalações;","VI - aos direitos e deveres dos usuários para obtenção e utilização do serviço;","VII - à forma de fiscalização das instalações, dos equipamentos, dos métodos e práticas de execução do serviço, bem como a indicação dos órgãos competentes para exercê-la;","VIII - às penalidades contratuais e administrativas a que se sujeita a concessionária e sua forma de aplicação;","IX - aos casos de extinção da concessão;","X - aos bens reversíveis;","XI - aos critérios para o cálculo e a forma de pagamento das indenizações devidas à concessionária, quando for o caso;","XII - às condições para prorrogação do contrato;","XIII - à obrigatoriedade, forma e periodicidade da prestação de contas da concessionária ao poder concedente;","XIV - à exigência da publicação de demonstrações financeiras periódicas da concessionária; e","XV - ao foro e ao modo amigável de solução das divergências contratuais.","XVI - (VETADO na Lei nº 13.448, de 5/6/2017)","Parágrafo único. Os contratos relativos à concessão de serviço público precedido da execução de obra pública deverão, adicionalmente:","I - estipular os cronogramas físico-financeiros de execução das obras vinculadas à concessão; e","II - exigir garantia do fiel cumprimento, pela concessionária, das obrigações relativas às obras vinculadas à concessão."],"url":""},{"key":"l8987:10","law":"l8987","ref":"10","label":"Lei de Concessões e Permissões · Art. 10","paragraphs":["Art. 10. Sempre que forem atendidas as condições do contrato, considera-se mantido seu equilíbrio econômico-financeiro."],"url":""},{"key":"l8987:35","law":"l8987","ref":"35","label":"Lei de Concessões e Permissões · Art. 35","paragraphs":["Art. 35. Extingue-se a concessão por:","I - advento do termo contratual;","II - encampação;","III - caducidade;","IV - rescisão;","V - anulação; e","VI - falência ou extinção da empresa concessionária e falecimento ou incapacidade do titular, no caso de empresa individual.","§ 1º Extinta a concessão, retornam ao poder concedente todos os bens reversíveis, direitos e privilégios transferidos ao concessionário conforme previsto no edital e estabelecido no contrato.","§ 2º Extinta a concessão, haverá a imediata assunção do serviço pelo poder concedente, procedendo-se aos levantamentos, avaliações e liquidações necessários.","§ 3º A assunção do serviço autoriza a ocupação das instalações e a utilização, pelo poder concedente, de todos os bens reversíveis.","§ 4º Nos casos previstos nos incisos I e II deste artigo, o poder concedente, antecipando-se à extinção da concessão, procederá aos levantamentos e avaliações necessários à determinação dos montantes da indenização que será devida à concessionária, na forma dos arts. 36 e 37 desta Lei."],"url":""},{"key":"l8987:36","law":"l8987","ref":"36","label":"Lei de Concessões e Permissões · Art. 36","paragraphs":["Art. 36. A reversão no advento do termo contratual far-se-á com a indenização das parcelas dos investimentos vinculados a bens reversíveis, ainda não amortizados ou depreciados, que tenham sido realizados com o objetivo de garantir a continuidade e atualidade do serviço concedido."],"url":""},{"key":"l8987:38","law":"l8987","ref":"38","label":"Lei de Concessões e Permissões · Art. 38","paragraphs":["Art. 38. A inexecução total ou parcial do contrato acarretará, a critério do poder concedente, a declaração de caducidade da concessão ou a aplicação das sanções contratuais, respeitadas as disposições deste artigo, do art. 27, e as normas convencionadas entre as partes.","§ 1º A caducidade da concessão poderá ser declarada pelo poder concedente quando:","I - o serviço estiver sendo prestado de forma inadequada ou deficiente, tendo por base as normas, critérios, indicadores e parâmetros definidores da qualidade do serviço;","II - a concessionária descumprir cláusulas contratuais ou disposições legais ou regulamentares concernentes à concessão;","III - a concessionária paralisar o serviço ou concorrer para tanto, ressalvadas as hipóteses decorrentes de caso fortuito ou força maior;","IV - a concessionária perder as condições econômicas, técnicas ou operacionais para manter a adequada prestação do serviço concedido;","V - a concessionária não cumprir as penalidades impostas por infrações, nos devidos prazos;","VI - a concessionária não atender a intimação do poder concedente no sentido de regularizar a prestação do serviço; e","VII - a concessionária não atender a intimação do poder concedente para, em 180 (cento e oitenta) dias, apresentar a documentação relativa a regularidade fiscal, no curso da concessão, na forma do art. 29 da Lei nº 8.666, de 21 de junho de 1993 . (Inciso com redação dada pela Medida Provisória nº 577, de 29/8/2012 , convertida na Lei nº 12.767, de 27/12/2012)","§ 2º A declaração da caducidade da concessão deverá ser precedida da verificação da inadimplência da concessionária em processo administrativo, assegurado o direito de ampla defesa.","§ 3º Não será instaurado processo administrativo de inadimplência antes de comunicados à concessionária, detalhadamente, os descumprimentos contratuais referidos no § 1º deste artigo, dando-lhe um prazo para corrigir as falhas e transgressões apontadas e para o enquadramento, nos termos contratuais.","§ 4º Instaurado o processo administrativo e comprovada a inadimplência, a caducidade será declarada por decreto do poder concedente, independentemente de indenização prévia, calculada no decurso do processo.","§ 5º A indenização de que trata o parágrafo anterior, será devida na forma do art. 36 desta Lei e do contrato, descontado o valor das multas contratuais e dos danos causados pela concessionária.","§ 6º Declarada a caducidade, não resultará para o poder concedente qualquer espécie de responsabilidade em relação aos encargos, ônus, obrigações ou compromissos com terceiros ou com empregados da concessionária."],"url":""},{"key":"l8987:3","law":"l8987","ref":"3","label":"Lei de Concessões e Permissões · Art. 3","paragraphs":["Art. 3º As concessões e permissões sujeitar-se-ão à fiscalização pelo poder concedente responsável pela delegação, com a cooperação dos usuários."],"url":""},{"key":"l8987:4","law":"l8987","ref":"4","label":"Lei de Concessões e Permissões · Art. 4","paragraphs":["Art. 4º A concessão de serviço público, precedida ou não da execução de obra pública, será formalizada mediante contrato, que deverá observar os termos desta Lei, das normas pertinentes e do edital de licitação."],"url":""},{"key":"l8987:12","law":"l8987","ref":"12","label":"Lei de Concessões e Permissões · Art. 12","paragraphs":["Art. 12. (VETADO)"],"url":""},{"key":"l8987:15","law":"l8987","ref":"15","label":"Lei de Concessões e Permissões · Art. 15","paragraphs":["Art. 15. No julgamento da licitação será considerado um dos seguintes critérios:","I - o menor valor da tarifa do serviço público a ser prestado; (Inciso com redação dada pela Lei nº 9.648, de 27/5/1998)","II - a maior oferta, nos casos de pagamento ao poder concedente pela outorga da concessão; (Inciso com redação dada pela Lei nº 9.648, de 27/5/1998)","III - a combinação, dois a dois, dos critérios referidos nos incisos I, II e VII; (Inciso com redação dada pela Lei nº 9.648, de 27/5/1998)","IV - melhor proposta técnica, com preço fixado no edital; (Inciso acrescido pela Lei nº 9.648, de 27/5/1998)","V - melhor proposta em razão da combinação dos critérios de menor valor da tarifa do serviço público a ser prestado com o de melhor técnica; (Inciso acrescido pela Lei nº 9.648, de 27/5/1998)","VI - melhor proposta em razão da combinação dos critérios de maior oferta pela outorga da concessão com o de melhor técnica; ou (Inciso acrescido pela Lei nº 9.648, de 27/5/1998)","VII - melhor oferta de pagamento pela outorga após qualificação de propostas técnicas. (Inciso acrescido pela Lei nº 9.648, de 27/5/1998)","§ 1º A aplicação do critério previsto no inciso III só será admitida quando previamente estabelecida no edital de licitação, inclusive com regras e fórmulas precisas para avaliação econômico-financeira. (Parágrafo com redação dada pela Lei nº 9.648, de 27/5/1998)","§ 2º Para fins de aplicação do disposto nos incisos IV, V, VI e VII, o edital de licitação conterá parâmetros e exigências para formulação de propostas técnicas. (Parágrafo com redação dada pela Lei nº 9.648, de 27/5/1998)","§ 3º O poder concedente recusará propostas manifestamente inexequíveis ou financeiramente incompatíveis com os objetivos da licitação. (Parágrafo com redação dada pela Lei nº 9.648, de 27/5/1998)","§ 4º Em igualdade de condições, será dada preferência à proposta apresentada por empresa brasileira. (Parágrafo acrescido pela Lei nº 9.648, de 27/5/1998)"],"url":""},{"key":"l8987:17","law":"l8987","ref":"17","label":"Lei de Concessões e Permissões · Art. 17","paragraphs":["Art. 17. Considerar-se-á desclassificada a proposta que, para sua viabilização, necessite de vantagens ou subsídios que não estejam previamente autorizados em lei e à disposição de todos os concorrentes.","§ 1º Considerar-se-á, também, desclassificada a proposta de entidade estatal alheia à esfera político-administrativa do poder concedente que, para sua viabilização, necessite de vantagens ou subsídios do poder público controlador da referida entidade. (Parágrafo único transformado em § 1º pela Lei nº 9.648, de 27/5/1998)","§ 2º Inclui-se nas vantagens ou subsídios de que trata este artigo, qualquer tipo de tratamento tributário diferenciado, ainda que em conseqüência da natureza jurídica do licitante, que comprometa a isonomia fiscal que deve prevalecer entre todos os concorrentes. (Parágrafo acrescido pela Lei nº 9.648, de 27/5/1998)"],"url":""},{"key":"l8987:23-A","law":"l8987","ref":"23-A","label":"Lei de Concessões e Permissões · Art. 23-A","paragraphs":["Art. 23-A. O contrato de concessão poderá prever o emprego de mecanismos privados para resolução de disputas decorrentes ou relacionadas ao contrato, inclusive a arbitragem, a ser realizada no Brasil e em língua portuguesa, nos termos da Lei nº 9.307, de 23 de setembro de 1996. (Artigo acrescido pela Lei nº 11.196, de 21/11/2005)"],"url":""},{"key":"l8987:24","law":"l8987","ref":"24","label":"Lei de Concessões e Permissões · Art. 24","paragraphs":["Art. 24. (VETADO)"],"url":""},{"key":"l8987:26","law":"l8987","ref":"26","label":"Lei de Concessões e Permissões · Art. 26","paragraphs":["Art. 26. É admitida a subconcessão, nos termos previstos no contrato de concessão, desde que expressamente autorizada pelo poder concedente.","§ 1º A outorga de subconcessão será sempre precedida de concorrência.","§ 2º O subconcessionário se sub-rogará todos os direitos e obrigações da subconcedente dentro dos limites da subconcessão."],"url":""},{"key":"l8987:27","law":"l8987","ref":"27","label":"Lei de Concessões e Permissões · Art. 27","paragraphs":["Art. 27. A transferência de concessão ou do controle societário da concessionária sem prévia anuência do poder concedente implicará a caducidade da concessão.","§ 1º Para fins de obtenção da anuência de que trata o caput deste artigo, o pretendente deverá:","I - atender às exigências de capacidade técnica, idoneidade financeira e regularidade jurídica e fiscal necessárias à assunção do serviço; e","II - comprometer-se a cumprir todas as cláusulas do contrato em vigor. (Parágrafo único transformado em § 1 º pela Lei nº 11.196, de 21/11/2005)","§ 2º (Parágrafo acrescido pela Lei nº 11.196, de 21/11/2005 e revogado pela Lei nº 13.097, de 19/1/2015)","§ 3º (Parágrafo acrescido pela Lei nº 11.196, de 21/11/2005 e revogado pela Lei nº 13.097, de 19/1/2015)","§ 4º (Parágrafo acrescido pela Lei nº 11.196, de 21/11/2005 e revogado pela Lei nº 13.097, de 19/1/2015)"],"url":""},{"key":"l8987:27-A","law":"l8987","ref":"27-A","label":"Lei de Concessões e Permissões · Art. 27-A","paragraphs":["Art. 27-A. Nas condições estabelecidas no contrato de concessão, o poder concedente autorizará a assunção do controle ou da administração temporária da concessionária por seus financiadores e garantidores com quem não mantenha vínculo societário direto, para promover sua reestruturação financeira e assegurar a continuidade da prestação dos serviços.","§ 1 º Na hipótese prevista no caput , o poder concedente exigirá dos financiadores e dos garantidores que atendam às exigências de regularidade jurídica e fiscal, podendo alterar ou dispensar os demais requisitos previstos no inciso I do parágrafo único do art. 27.","§ 2 º A assunção do controle ou da administração temporária autorizadas na forma do caput deste artigo não alterará as obrigações da concessionária e de seus controladores para com terceiros, poder concedente e usuários dos serviços públicos.","§ 3 º Configura-se o controle da concessionária, para os fins dispostos no caput deste artigo, a propriedade resolúvel de ações ou quotas por seus financiadores e garantidores que atendam os requisitos do art. 116 da Lei no 6.404, de 15 de dezembro de 1976.","§ 4 º Configura-se a administração temporária da concessionária por seus financiadores e garantidores quando, sem a transferência da propriedade de ações ou quotas, forem outorgados os seguintes poderes:","I - indicar os membros do Conselho de Administração, a serem eleitos em Assembleia Geral pelos acionistas, nas sociedades regidas pela Lei 6.404, de 15 de dezembro de 1976; ou administradores, a serem eleitos pelos quotistas, nas demais sociedades;","II - indicar os membros do Conselho Fiscal, a serem eleitos pelos acionistas ou quotistas controladores em Assembleia Geral;","III - exercer poder de veto sobre qualquer proposta submetida à votação dos acionistas ou quotistas da concessionária, que representem, ou possam representar, prejuízos aos fins previstos no caput deste artigo;","IV - outros poderes necessários ao alcance dos fins previstos no caput deste artigo.","§ 5 º A administração temporária autorizada na forma deste artigo não acarretará responsabilidade aos financiadores e garantidores em relação à tributação, encargos, ônus, sanções, obrigações ou compromissos com terceiros, inclusive com o poder concedente ou empregados.","§ 6 º O Poder Concedente disciplinará sobre o prazo da administração temporária. (Artigo acrescido pela Lei nº 13.097, de 19/1/2015)"],"url":""},{"key":"l8987:28","law":"l8987","ref":"28","label":"Lei de Concessões e Permissões · Art. 28","paragraphs":["Art. 28. Nos contratos de financiamento, as concessionárias poderão oferecer em garantia os direitos emergentes da concessão, até o limite que não comprometa a operacionalização e a continuidade da prestação do serviço.","Parágrafo único. (Revogado pela Lei nº 9.074, de 7/7/1995)"],"url":""},{"key":"l8987:28-A","law":"l8987","ref":"28-A","label":"Lei de Concessões e Permissões · Art. 28-A","paragraphs":["Art. 28-A. Para garantir contratos de mútuo de longo prazo, destinados a investimentos relacionados a contratos de concessão, em qualquer de suas modalidades, as concessionárias poderão ceder ao mutuante, em caráter fiduciário, parcela de seus créditos operacionais futuros, observadas as seguintes condições:","I - o contrato de cessão dos créditos deverá ser registrado em Cartório de Títulos e Documentos para ter eficácia perante terceiros;","II - sem prejuízo do disposto no inciso I do caput deste artigo, a cessão do crédito não terá eficácia em relação ao Poder Público concedente senão quando for este formalmente notificado;","III - os créditos futuros cedidos nos termos deste artigo serão constituídos sob a titularidade do mutuante, independentemente de qualquer formalidade adicional;","IV - o mutuante poderá indicar instituição financeira para efetuar a cobrança e receber os pagamentos dos créditos cedidos ou permitir que a concessionária o faça, na qualidade de representante e depositária;","V - na hipótese de ter sido indicada instituição financeira, conforme previsto no inciso IV do caput deste artigo, fica a concessionária obrigada a apresentar a essa os créditos para cobrança;","VI - os pagamentos dos créditos cedidos deverão ser depositados pela concessionária ou pela instituição encarregada da cobrança em conta corrente bancária vinculada ao contrato de mútuo;","VII - a instituição financeira depositária deverá transferir os valores recebidos ao mutuante à medida que as obrigações do contrato de mútuo tornarem-se exigíveis; e","VIII - o contrato de cessão disporá sobre a devolução à concessionária dos recursos excedentes, sendo vedada a retenção do saldo após o adimplemento integral do contrato.","Parágrafo único. Para os fins deste artigo, serão considerados contratos de longo prazo aqueles cujas obrigações tenham prazo médio de vencimento superior a 5 (cinco) anos. (Artigo acrescido pela Lei nº 11.196, de 21/11/2005)"],"url":""},{"key":"l8987:32","law":"l8987","ref":"32","label":"Lei de Concessões e Permissões · Art. 32","paragraphs":["Art. 32. O poder concedente poderá intervir na concessão, com o fim de assegurar a adequação na prestação do serviço, bem como o fiel cumprimento das normas contratuais, regulamentares e legais pertinentes.","Parágrafo único. A intervenção far-se-á por decreto do poder concedente, que conterá a designação do interventor, o prazo da intervenção e os objetivos e limites da medida."],"url":""},{"key":"l8987:33","law":"l8987","ref":"33","label":"Lei de Concessões e Permissões · Art. 33","paragraphs":["Art. 33. Declarada a intervenção, o poder concedente deverá, no prazo de trinta dias, instaurar procedimento administrativo para comprovar as causas determinantes da medida e apurar responsabilidades, assegurado o direito de ampla defesa.","§ 1º Se ficar comprovado que a intervenção não observou os pressupostos legais e regulamentares será declarada sua nulidade, devendo o serviço ser imediatamente devolvido à concessionária, sem prejuízo de seu direito à indenização.","§ 2º O procedimento administrativo a que se refere o caput deste artigo deverá ser concluído no prazo de até cento e oitenta dias, sob pena de considerar-se inválida a intervenção."],"url":""},{"key":"l8987:34","law":"l8987","ref":"34","label":"Lei de Concessões e Permissões · Art. 34","paragraphs":["Art. 34. Cessada a intervenção, se não for extinta a concessão, a administração do serviço será devolvida à concessionária, precedida de prestação de contas pelo interventor, que responderá pelos atos praticados durante a sua gestão."],"url":""},{"key":"l8987:37","law":"l8987","ref":"37","label":"Lei de Concessões e Permissões · Art. 37","paragraphs":["Art. 37. Considera-se encampação a retomada do serviço pelo poder concedente durante o prazo da concessão, por motivo de interesse público, mediante lei autorizativa específica e após prévio pagamento da indenização, na forma do artigo anterior."],"url":""},{"key":"l8987:39","law":"l8987","ref":"39","label":"Lei de Concessões e Permissões · Art. 39","paragraphs":["Art. 39. O contrato de concessão poderá ser rescindido por iniciativa da concessionária, no caso de descumprimento das normas contratuais pelo poder concedente, mediante ação judicial especialmente intentada para esse fim.","Parágrafo único. Na hipótese prevista no caput deste artigo, os serviços prestados pela concessionária não poderão ser interrompidos ou paralisados, até a decisão judicial transitada em julgado."],"url":""},{"key":"l9074:1","law":"l9074","ref":"1","label":"Lei 9.074/1995 · Art. 1","paragraphs":["Art. 1º Sujeitam-se ao regime de concessão ou, quando couber, de permissão, nos termos da Lei nº 8.987, de 13 de fevereiro de 1995, os seguintes serviços e obras públicas de competência da União:","I - (VETADO)","II - (VETADO)","III - (VETADO)","IV - vias federais, precedidas ou não da execução de obra pública;","V - exploração de obras ou serviços federais de barragens, contenções, eclusas ou outros dispositivos de transposição hidroviária de níveis, diques, irrigações, precedidas ou não da execução de obras públicas; (Inciso com redação dada pela Lei nº 13.081, de 2/1/2015)","VI - estações aduaneiras e outros terminais alfandegados de uso público, não instalados em área de porto ou aeroporto, precedidos ou não de obras públicas;","VII - os serviços postais. (Inciso acrescido pela Lei nº 9.648, de 27/5/1998)","§ 1º (Revogado pela Lei nº 11.668, de 2/5/2008)","§ 2º O prazo das concessões e permissões de que trata o inciso VI deste artigo será de vinte e cinco anos, podendo ser prorrogado por dez anos. (Parágrafo acrescido pela Lei nº 10.684, de 30/5/2003) (Vide ADI nº 3.497/2005)","§ 3º Ao término do prazo, as atuais concessões e permissões, mencionadas no § 2º, incluídas as anteriores à Lei nº 8.987, de 13 de fevereiro de 1995, serão prorrogadas pelo prazo previsto no § 2º. (Parágrafo acrescido pela Lei nº 10.684, de 30/5/2003) (Vide ADI nº 3.497/2005)"],"url":""},{"key":"ctn:77","law":"ctn","ref":"77","label":"Código Tributário Nacional · Art. 77","paragraphs":["Art. 77. As taxas cobradas pela União, pelos Estados, pelo Distrito Federal ou pelos Municípios, no âmbito de suas respectivas atribuições, têm como fato gerador o exercício regular do poder de polícia, ou a utilização, efetiva ou potencial, de serviço público específico e divisível, prestado ao contribuinte ou posto à sua disposição.","Parágrafo único. A taxa não pode ter base de cálculo ou fato gerador idênticos aos que correspondam a imposto, nem ser calculada em função do capital das empresas. (Expressão “nem ser calculada em função do capital das empresas\" acrescida pelo Ato Complementar nº 34, de 30/1/1967)"],"url":""},{"key":"ctn:79","law":"ctn","ref":"79","label":"Código Tributário Nacional · Art. 79","paragraphs":["Art. 79. Os serviços públicos a que se refere o art. 77 consideram-se:","I - utilizados pelo contribuinte:","a) efetivamente, quando por ele usufruídos a qualquer título;","b) potencialmente, quando, sendo de utilização compulsória, sejam postos à sua disposição mediante atividade administrativa em efetivo funcionamento;","II - específicos, quando possam ser destacados em unidades autônomas de intervenção, de utilidade ou de necessidade públicas;","III - divisíveis, quando suscetíveis de utilização, separadamente, por parte de cada um dos seus usuários."],"url":""}];})(window);
